class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        left = 0
        ans = 0
        n = len(nums)

        for right in range(n):
            # Check conditions: 
            # nums[left] % 2 != 0 OR nums[left] > threshold OR nums[right] > threshold OR (right > 0 AND nums[right] % 2 == nums[right - 1] % 2)
            if nums[left] % 2 != 0 or nums[left] > threshold or nums[right] > threshold or (right > 0 and nums[right] % 2 == nums[right - 1] % 2):
                left = right
            else:
                # Check if nums[left] % 2 == 0 AND nums[left] <= threshold
                if nums[left] % 2 == 0 and nums[left] <= threshold:
                    ans = max(ans, right - left + 1)
                else:
                    left = right

        return ans
